// Arimo font weights (Apache-2.0), LATIN-SUBSET, bundled as base64 so the CV
// PDF renderer has NO runtime network fetch. Arimo is metric-compatible with
// Arial/Helvetica (visually ~identical output) and these subsets carry the full
// Latin range, which the previous WinAnsi StandardFonts.Helvetica* embeds lacked
// (they threw on any non-WinAnsi glyph, e.g. the "a" with macron U+0101).
//
// Provenance: github.com/googlefonts/Arimo, fonts/ttf/, commit 4a6255f269916ae7ad3fc2706b0935e7621396b8 (Apache-2.0).
// Subset with fonttools/pyftsubset:
//   pyftsubset Arimo-<Weight>.ttf --unicodes="U+0000-007F,U+0080-00FF,U+0100-017F,U+0180-024F,U+1E00-1EFF,U+2022,U+2014,U+00B7,U+20AC" --output-file=...
// Ranges: Basic Latin, Latin-1 Supplement, Latin Extended-A/-B, Latin Extended
// Additional, plus bullet U+2022, em dash U+2014, middle dot U+00B7, euro U+20AC.
// Non-Latin scripts (Hebrew, etc.) are deliberately NOT in these subsets, so the
// cmap-driven sanitizer in build-pdf.ts drops them cleanly. Per-file (subset):
//   Arimo-Regular: 73.2 KB
//   Arimo-Bold: 74.7 KB
//   Arimo-Italic: 77.9 KB
//   Arimo-BoldItalic: 78.8 KB

const decode = (b64: string): Uint8Array =>
  Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));

export const ARIMO_REGULAR: Uint8Array = decode(
  "",
);

export const ARIMO_BOLD: Uint8Array = decode(
  "",
);

export const ARIMO_ITALIC: Uint8Array = decode(
  "",
);

export const ARIMO_BOLDITALIC: Uint8Array = decode(
  "",
);

